import glob,gzip,collections
c=collections.Counter()
for f in sorted(glob.glob('exports/*/*')):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': print('gz',f); b=gzip.decompress(b)
    if b'\r\n' in b: c['crlf']+=1
    if b[:3]==b'\xef\xbb\xbf': print('bom',f)
    t=b.decode()
    s=f.split('/')[1]
    if s in('harbor-point','southbank'):
        hs=[l for l in t.splitlines() if l.startswith(('Badge','Record'))]
        if len(hs)>1 or hs[0] not in('Badge,Punch,Date,Time,Zone,Terminal,Record',): print(f,hs)
    if s=='kiln':
        hs=[l for l in t.splitlines() if l[:1] in 'HT']
        if len(hs)!=2 or len(hs[0])!=13: print(f,hs)
    if s=='ridgeline':
        for l in t.splitlines():
            if 'schema' in l: print(f,l)
print(c)
E
